def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: A time-like object.
    :type value: datetime.time
    :return: ISO formatted string representation of the time, or None if value is None.
    :raises TypeError: If value does not support conversion to ISO format.
    """
    if value is None:
        return None
    try:
        # The default isoformat() handles nested time objects and returns a string.
        return value.isoformat()
    except Exception as exc:
        raise TypeError(f"Expected a time-like object, got {type(value).__name__}") from exc<|return|>

def dehydrate_point(value):
    """Dehydrat of a point-like object into a JSON‑serialisable dict.

    Accepts an object with numeric attributes `x` and `y` (optional `z`), or a
    sequence of 2 or 3 numeric items.  If :data:`value` is ``None`` the
    function returns ``None``.  Any other type raises :class:`TypeError`.

    Parameters
    ----------
    value : Any
        The point to dehydrate.

    Returns
    -------
    dict or None
        A mapping ``{'x': ..., 'y': ..., 'z': ...}`` containing the point
        coordinates, or ``None`` if the input was ``None``.
    """
    if value is None:
        return None

    # Handle simple sequences (tuple or list) first.
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            x, y = value
            return {'x': x, 'y': y}
        elif len(value) == 3:
            x, y, z = value
            return {'x': x, 'y': y, 'z': z}
        else:
            raise TypeError(
                "Sequence must contain 2 or 3 numeric elements to represent a point."
            )

    # Attempt to pull attributes from an arbitrary object.
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
    except AttributeError as exc:
        raise TypeError(
            "Expected an object with attributes 'x' and 'y', "
            f"but got {type(value).__name__}"
        ) from exc

    # Optional z coordinate.
    z = getattr(value, "z", None)

    # Verify that coordinates are numeric.
    for name, coord in (("x", x), ("y", y)):
        if not isinstance(coord, (int, float)):
            raise TypeError(f"Attribute '{name}' must be int or float, got {type(coord).__name__}")

    if z is not None:
        if not isinstance(z, (int, float)):
            raise TypeError(f"Attribute 'z' must be int or float, got {type(z).__name__}")
        return {"x": x, "y": y, "z": z}

    return {"x": x, "y": y}<|return|>

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Assume the record data is stored in a dictionary-like attribute named `_data`.
        data = getattr(self, "_data", {})
        if isinstance(data, dict):
            return list(data.keys())
        # If `_data` is not a dict, try to introspect any dict-like structure.
        if hasattr(data, "keys") and callable(data.keys):
            return list(data.keys())
    except Exception:
        # Silently return an empty list in case of any unexpected issue.
        pass
    return []<|return|>

def unit_of_work(metadata=None, timeout=None):
    """A no-op decorator that validates the `metadata` and `timeout` arguments.
    The decorator returns a wrapper that simply calls the wrapped function.
    The wrapper will propagate any exception raised by the wrapped function.
    """
    # Validate decorator arguments
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError(f"metadata must be a dict or None, got {type(metadata).__name__}")
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError(f"timeout must be a number or None, got {type(timeout).__name__}")
        if timeout < 0:
            raise ValueError("timeout must not be negative")

    def decorator(func):
        if not callable(func):
            raise TypeError("unit_of_work decorator expects a callable, got %r" % (func,))

        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception:  # re-raise any exception so callers see original error
                raise

        # Preserve function attributes
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator<|return|>

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Determine the underlying sequence to search
    seq = None
    if hasattr(self, 'data'):
        seq = getattr(self, 'data')
    elif hasattr(self, '_data'):
        seq = getattr(self, '_data')
    else:
        try:
            seq = list(self)
        except TypeError:
            raise TypeError("object has no 'data' or '_data' attribute and is not iterable") from None

    # Attempt to use the built-in index method if available
    if hasattr(seq, 'index'):
        try:
            return seq.index(key)
        except ValueError:
            # Fall through to custom loop for consistent error handling
            pass

    # Linear search as a fallback
    for idx, item in enumerate(seq):
        if item == key:
            return idx
    raise ValueError(f"{key!r} is not in the container")<|return|>

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to include only
    certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to retrieve the underlying data container
    try:
        data = self._data
    except AttributeError as e:
        # The object doesn't expose a `_data` attribute; raise a clear error
        raise AttributeError(
            "The object does not expose a `_data` attribute required for values()"
        ) from e

    if not isinstance(data, dict):
        # If `_data` is not a dict, we cannot guarantee ordering or key lookup
        raise TypeError(
            f"_data must be a dict to support values(), got {type(data).__name__}"
        )

    # Preserve insertion order for indexing
    values_list = list(data.values())

    # If no keys specified, return all values
    if not keys:
        return values_list

    # Build the result list based on the supplied keys
    result = []
    for key in keys:
        if isinstance(key, int):
            # Handle negative indices as Python list indexing does
            try:
                result.append(values_list[key])
            except IndexError as e:
                raise IndexError(
                    f"Index {key} is out of range for values list of length {len(values_list)}"
                ) from e
        else:
            # Treat as a dict key
            try:
                result.append(data[key])
            except KeyError as e:
                raise KeyError(
                    f"Key {key!r} not found in record"
                ) from e

    return result<|return|>

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
             hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response-like object representing the DISCARD operation
    """
    # Basic type validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(qid, int):
        raise TypeError("qid must be an integer")

    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary")
        for typ, func in dehydration_hooks.items():
            if not isinstance(typ, type) or not callable(func):
                raise ValueError("dehydration_hooks keys must be types and values must be callables")

    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary")
        for typ, func in hydration_hooks.items():
            if not isinstance(typ, type) or not callable(func):
                raise ValueError("hydration_hooks keys must be types and values must be callables")

    # Create the DISCARD message payload
    message = {
        "message_type": "DISCARD",
        "n": n,
        "qid": qid
    }

    # Attach hooks to the message so the packer can use them
    if dehydration_hooks:
        message["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks:
        message["hydration_hooks"] = hydration_hooks

    # Append the message to the output queue
    try:
        queue = getattr(self, "_output_queue", None)
        if queue is None:
            # Fallback to a generic 'output' attribute
            queue = getattr(self, "output", None)
            if queue is None:
                raise AttributeError("No output queue found on the object")
        queue.append(message)
    except Exception as exc:
        raise RuntimeError(f"Failed to append DISCARD message: {exc}") from exc

    # Define a lightweight Response-like object to carry metadata
    class _Response:
        def __init__(self, query_id, num_records, handlers,
                     dehydration, hydration):
            self.query_id = query_id
            self.num_records = num_records
            self.handlers = handlers
            self.dehydration_hooks = dehydration
            self.hydration_hooks = hydration

        def __repr__(self):
            return (f"_Response(query_id={self.query_id}, "
                    f"num_records={self.num_records}, "
                    f"handlers={list(self.handlers.keys())})")

    return _Response(qid, n, handlers, dehydration_hooks, hydration_hooks)<|return|>

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass."""
    # Attempt to import the base Point class from shapely
    try:
        from shapely.geometry import Point
    except Exception as exc:
        raise ImportError("shapely library is required to create point types.") from exc

    # Input validation
    if not isinstance(name, str) or not name:
        raise ValueError("The 'name' argument must be a non-empty string.")
    if not isinstance(fields, dict):
        raise TypeError("The 'fields' argument must be a dictionary.")
    if not isinstance(srid_map, dict):
        raise TypeError("The 'srid_map' argument must be a dictionary.")

    # Construct the class dictionary
    class_dict = {}

    # Add default values for extra fields
    for field_name, default_value in fields.items():
        if not isinstance(field_name, str):
            raise TypeError("Field names must be strings.")
        class_dict[field_name] = default_value

    # Define __init__ for the dynamic subclass
    def __init__(self, x, y, srid=None, **extra_attrs):
        # Call the parent constructor
        super(self.__class__, self).__init__(x, y)
        # Store srid
        self._srid = srid
        # Store any extra attributes; only store those defined in 'fields' if present
        for key, value in extra_attrs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                # Allow arbitrary attributes that are not part of 'fields'
                setattr(self, key, value)

    class_dict["__init__"] = __init__

    # Property to expose srid
    def _get_srid(self):
        return getattr(self, "_srid", None)

    class_dict["srid"] = property(_get_srid)

    # Attach the srid_map to the class
    class_dict["srid_map"] = srid_map

    # Friendly __repr__ to help debugging
    def __repr__(self):
        base_repr = f"<{name} ({self.x}, {self.y})"
        if self.srid is not None:
            base_repr += f" SRID={self.srid}"
        if fields:
            extra_reprs = ", ".join(f"{k}={getattr(self, k, None)}" for k in fields)
            base_repr += f", {extra_reprs}"
        base_repr += ">"
        return base_repr

    class_dict["__repr__"] = __repr__

    # Dynamically create and return the new subclass
    return type(name, (Point,), class_dict)<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison: extract all integer sequences from the
    input string, interpreting them in order. Non-digit separators are ignored.
    Examples:
        parse_version('1.2.3')       -> (1, 2, 3)
        parse_version('v2.0beta4')   -> (2, 0, 4)
        parse_version('')            -> ()
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    numbers = []
    current = ''
    for ch in s:
        if ch.isdigit():
            current += ch
        else:
            if current:
                numbers.append(int(current))
                current = ''
    if current:
        numbers.append(int(current))
    return tuple(numbers)<|return|>

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorating_function(user_function):
        from collections import OrderedDict

        # Prepare the key-making function
        if typed:
            def make_key(*args, **kwargs):
                try:
                    key_parts = list(args)
                    if kwargs:
                        key_parts += sorted(kwargs.items())
                    key = (
                        tuple(key_parts),
                        tuple(type(v) for v in args),
                        tuple((k, type(v)) for k, v in sorted(kwargs.items())),
                    )
                    return key
                except Exception as exc:
                    raise KeyError("Failed to create cache key") from exc
        else:
            def make_key(*args, **kwargs):
                try:
                    key_parts = list(args)
                    if kwargs:
                        key_parts += sorted(kwargs.items())
                    return tuple(key_parts)
                except Exception as exc:
                    raise KeyError("Failed to create cache key") from exc

        cache = OrderedDict()

        def wrapper(*args, **kwargs):
            key = make_key(*args, **kwargs)
            if key in cache:
                # Move key to end to mark it as recently used
                value = cache.pop(key)
                cache[key] = value
                return value
            # Compute the result and store it in cache
            result = user_function(*args, **kwargs)
            cache[key] = result
            # Ensure cache size limit
            if len(cache) > maxsize:
                cache.popitem(last=False)  # pop least recently used item
            return result

        # Provide a simple cache_info and cache_clear attribute for introspection
        wrapper.cache_clear = cache.clear

        def cache_info():
            return {
                "maxsize": maxsize,
                "currsize": len(cache),
                "hits": None,
                "misses": None,
                "maxsize": maxsize,
            }

        wrapper.cache_info = cache_info

        return wrapper

    return decorating_function<|return|>

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            # Determine the cache key
            try:
                if callable(key):
                    lookup_key = key(self, *args, **kwargs)
                else:
                    # If key is not callable, use it as a prefix
                    lookup_key = (key, args, tuple(sorted(kwargs.items())))
            except Exception:
                # Fallback to a default key if key callable fails
                lookup_key = (func.__name__, args, tuple(sorted(kwargs.items())))

            # Retrieve from cache if available
            if lock:
                with lock:
                    if lookup_key in cache:
                        return cache[lookup_key]
            else:
                if lookup_key in cache:
                    return cache[lookup_key]

            # Compute the value, cache it, and return it
            result = func(self, *args, **kwargs)
            if lock:
                with lock:
                    cache[lookup_key] = result
            else:
                cache[lookup_key] = result
            return result

        return wrapper
    return decorator<|return|>

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """Load a file toward a text buffer (UTF-8), using the specify encoding while reading.

        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype: str | None
        """
        # Validate input types
        if not isinstance(file_name, str) or not isinstance(encoding, str):
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as f:
                return f.read()
        except (FileNotFoundError, OSError, UnicodeDecodeError, LookupError):
            return None<|return|>

def _getTargetClass(self):
        """
        Define this to return the implementation in use,
        without the 'Py' or 'Fallback' suffix.
        """
        try:
            name = self.__class__.__name__
            # Strip 'Py' or 'Fallback' suffixes
            for suffix in ("Py", "Fallback"):
                if name.endswith(suffix):
                    name = name[: -len(suffix)]
            # Strip any leading 'Py' if present
            if name.startswith("Py"):
                name = name[2:]
            return name
        except Exception:
            # In case of unexpected errors, return an empty string
            return ""<|return|>

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        required = _c_optimizations_required()
        # If the required function returns a boolean, simply negate it.
        if isinstance(required, bool):
            return not required
        # If it returns something truthy/falsy, treat accordingly.
        return not bool(required)
    except NameError:
        # _c_optimizations_required is not defined; assume optimizations are ignored.
        return True
    except Exception as e:
        # Any other exception: log or ignore and default to True.
        return True<|return|>

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset the context.
        self.context = {}

        # Reinitialize bins.
        if hasattr(self, 'initial_value') and self.initial_value is not None:
            # Use the provided initial value directly.
            self.bins = self.initial_value
        elif hasattr(self, 'make_bins') and callable(self.make_bins):
            # Fallback to the factory method if defined.
            self.bins = self.make_bins()
        else:
            # As a safety net, set to an empty dict if no bin definition is available.
            self.bins = {}
    except Exception as exc:
        raise RuntimeError("Cannot reset histogram: %s" % exc) from exc<|return|>

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Validate input type
        if not isinstance(coord_name, str):
            raise TypeError("coord_name must be a string")

        # Attempt to locate the error indices mapping on the instance.
        # Look for a private attribute first, then a public one.
        err_map = getattr(self, "_err_indices", None)
        if err_map is None:
            err_map = getattr(self, "err_indices", None)

        if err_map is None:
            raise AttributeError(
                "The instance has no error indices mapping (_err_indices or err_indices)."
            )

        # If the mapping is a dict, look up the coordinate name directly.
        if isinstance(err_map, dict):
            if coord_name in err_map:
                result = err_map[coord_name]
                # Return a copy if the stored value is mutable to prevent side‑effects.
                if isinstance(result, (list, set, dict)):
                    return result.copy()
                return result
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices mapping.")

        # If the mapping is an ordered sequence (list/tuple), try to find the index.
        try:
            idx = err_map.index(coord_name)
            return idx
        except (AttributeError, ValueError):
            # The mapping might be a sequence of tuples like [(coord, indices), ...]
            for entry in err_map:
                try:
                    if entry[0] == coord_name:
                        return entry[1]
                except (IndexError, TypeError):
                    continue
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices structure.")<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # basic input validation
    try:
        bins_list = list(bins)
    except Exception as exc:
        raise TypeError(f"bins must be an iterable of numbers, got {type(bins)}") from exc
    try:
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError(f"edges must be an iterable of numbers, got {type(edges)}") from exc

    if not edges_list:
        raise ValueError("edges cannot be empty")
    if not bins_list:
        # Empty histogram – integral is zero
        return 0.0

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("edges length must be one greater than bins length")

    # Compute widths and check for non-positive widths
    widths = []
    for i in range(len(bins_list)):
        try:
            left = float(edges_list[i])
            right = float(edges_list[i + 1])
        except Exception as exc:
            raise TypeError(f"Edge values must be convertible to float, got {edges_list[i]} and {edges_list[i+1]}") from exc
        width = right - left
        if width < 0:
            raise ValueError(f"Bin width negative between edges[{i}]={edges_list[i]} and edges[{i+1}]={edges_list[i+1]}")
        widths.append(width)

    # Compute integral
    integral_value = 0.0
    for b, w in zip(bins_list, widths):
        try:
            bin_val = float(b)
        except Exception as exc:
            raise TypeError(f"Bin value must be convertible to float, got {b}") from exc
        integral_value += bin_val * w

    return integral_value<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # First, avoid treating a Source sequence as a fill request sequence
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source type not defined; ignore this check
        pass

    # If the sequence itself is a single FillRequest, return True
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest type not defined; cannot use isinstance
        pass

    # Try to iterate over seq; if not iterable, return False
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Exclude string/bytes from being treated as a sequence of items
    if isinstance(seq, (str, bytes)):
        return False

    # Check each element of the sequence
    for item in iterator:
        try:
            if isinstance(item, FillRequest):
                # Ensure the original sequence wasn't a Source
                try:
                    if isinstance(seq, Source):
                        return False
                except NameError:
                    pass
                return True
        except NameError:
            # If FillRequest type is undefined, skip using isinstance
            pass

    # No FillRequest found in the sequence
    return False<|return|>

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (
            hasattr(obj, 'fill')
            and hasattr(obj, 'request')
            and callable(getattr(obj, 'fill', None))
            and callable(getattr(obj, 'request', None))
        )
    except Exception:
        return False<|return|>

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        method = getattr(obj, 'run')
    except Exception:
        return False
    return callable(method)<|return|>

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False<|return|>

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        try:
            # Basic validation of inputs
            if not isinstance(coord, (tuple, list, np.ndarray)):
                raise TypeError("coord must be a tuple/list/Numpy array with 2 numeric elements.")
            if len(coord) != 2:
                raise ValueError("coord must contain exactly two values.")

            # Ensure weight is numeric
            if not isinstance(weight, (int, float, np.number)):
                raise TypeError("weight must be a numeric value.")

            # Retrieve histogram edges (assumed to be a list/tuple of two 1D arrays)
            edges_x, edges_y = self.edges

            # Check if the coordinate falls within the valid range
            if not (edges_x[0] <= coord[0] < edges_x[-1]):
                return
            if not (edges_y[0] <= coord[1] < edges_y[-1]):
                return

            # Find the appropriate bin indices using digitize
            bin_x = np.digitize(coord[0], edges_x) - 1
            bin_y = np.digitize(coord[1], edges_y) - 1

            # Ensure indices are within histogram bounds
            if not (0 <= bin_x < self.hist.shape[0]) or not (0 <= bin_y < self.hist.shape[1]):
                return

            # Increment the histogram bin with the given weight
            self.hist[bin_x, bin_y] += weight

        except Exception as exc:
            raise RuntimeError(f"Failed to fill histogram at {coord} with weight {weight}: {exc}") from exc<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a Kubernetes resource dictionary.

    This function recursively walks ``manifest_dict`` creating a new dictionary where
    all non-dict and non-list leaf values are replaced with ``None``.  When
    ``first_level`` is ``True`` the function copies the values of identified
    fields from the original ``manifest_dict`` (e.g. ``name``, ``namespace``,
    ``apiVersion`` and ``kind``).

    Parameters
    ----------
    manifest_dict : dict
