    if manifest_dict is None:
        return {}
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected dict, got {type(manifest_dict).__name__}")

    # Identify fields that should be preserved at the top level
    _IDENTIFY_FIELDS = {"name", "namespace", "apiVersion", "kind"}

    def _process(obj, is_first_level: bool):
        if isinstance(obj, dict):
            new_obj = {}
            for key, val in obj.items():
                if isinstance(val, dict):
                    new_obj[key] = _process(val, False)
                elif isinstance(val, list):
                    new_list = []
                    for item in val:
                        if isinstance(item, (dict, list)):
                            new_list.append(_process(item, False))
                        else:
                            new_list.append(None)
                    new_obj[key] = new_list
                else:
                    # Preserve identifying fields at the top level
                    if is_first_level and key in _IDENTIFY_FIELDS:
                        new_obj[key] = val
                    else:
                        new_obj[key] = None
            return new_obj
        elif isinstance(obj, list):
            return [_process(item, is_first_level) for item in obj]
        else:
            return None

    return _process(manifest_dict, first_level)
