def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    The function iterates over all observed fields defined in
    ``observer_schema`` and ensures that the corresponding entry in
    ``last_applied_manifest`` is initialized with the value from
    ``response`` if it is not already set.  Nested structures are handled
    recursively by delegating to the appropriate helper function.

    Args:
        last_applied_manifest (list): The partially built manifest that is
            being updated.
        observer_schema (list): The schema describing which fields should be
            considered.  Each element can be a simple value (ignored here),
            a dict describing a nested mapping, or a list describing a nested
            list.
        response (list): The partial Kubernetes API response that contains
            the actual values.

    Returns:
        list: The updated ``last_applied_manifest`` list.

    Raises:
        TypeError: If any of the inputs is not of the expected type.
    """
    import collections.abc

    # Basic type checking
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Iterate over the observer schema; limit to the length of the response
    for idx, schema_item in enumerate(observer_schema):
        if idx >= len(response):
            break

        resp_val = response[idx]

        # Handle nested dictionaries
        if isinstance(schema_item, dict):
            if isinstance(resp_val, dict):
                # Ensure a dict is present in the manifest at this index
                if idx < len(last_applied_manifest):
                    manifest_val = last_applied_manifest[idx]
                    if not isinstance(manifest_val, dict):
                        last_applied_manifest[idx] = {}
                else:
                    last_applied_manifest.append({})
                # Recursively update the nested dict
                try:
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx], schema_item, resp_val
                    )
                except Exception:
                    # If the helper fails we fall back to a shallow copy
                    last_applied_manifest[idx] = resp_val
            else:
                # A non-dict value should be set directly if uninitialized
                if idx < len(last_applied_manifest):
                    if last_applied_manifest[idx] is None:
                        last_applied_manifest[idx] = resp_val
                else:
                    last_applied_manifest.append(resp_val)

        # Handle nested lists
        elif isinstance(schema_item, list):
            if isinstance(resp_val, list):
                # Ensure a list is present at this index
                if idx < len(last_applied_manifest):
                    manifest_val = last_applied_manifest[idx]
                    if not isinstance(manifest_val, list):
                        last_applied_manifest[idx] = []
                else:
                    last_applied_manifest.append([])
                # Recursively update the nested list
                try:
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[idx], schema_item, resp_val
                    )
                except Exception:
                    # If recursion fails, fallback to the raw value
                    last_applied_manifest[idx] = resp_val
            else:
                # A non-list value should be set directly if uninitialized
                if idx < len(last_applied_manifest):
                    if last_applied_manifest[idx] is None:
                        last_applied_manifest[idx] = resp_val
                else:
                    last_applied_manifest.append(resp_val)

        # Handle simple scalar schema items (keys or values)
        else:
            if idx < len(last_applied_manifest):
                if last_applied_manifest[idx] is None:
                    last_applied_manifest[idx] = resp_val
            else:
                last_applied_manifest.append(resp_val)

    return last_applied_manifest
<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively update a partial ``last_applied_manifest`` from a partial
    Kubernetes response according to ``observer_schema``.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated.
        observer_schema (dict): mapping of field names to their schema.
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If an observed field is not present in the Kubernetes response.
        ValueError: If a field expected to be a dict or a list does not match
            the actual type in the response.
    """
    if not isinstance(observer_schema, dict):
        # Nothing to update
        return

    for field_name, field_spec in observer_schema.items():
        # Ensure the field exists in the response
        if field_name not in response:
            raise KeyError(f"Observed field {field_name!r} missing from Kubernetes response")

        resp_value = response[field_name]
        # When the field is a nested dict
        if isinstance(field_spec, dict):
            if not isinstance(resp_value, dict):
                raise ValueError(
                    f"Expected dict for field {field_name!r} but got {type(resp_value).__name__}"
                )
            # Initialize nested dict if missing
            if field_name not in last_applied_manifest or not isinstance(
                last_applied_manifest[field_name], dict
            ):
                last_applied_manifest[field_name] = {}
            # Recurse into nested dict
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field_name],
                field_spec,
                resp_value,
            )
        # When the field is a list (schema described by a list)
        elif isinstance(field_spec, list):
            if not isinstance(resp_value, list):
                raise ValueError(
                    f"Expected list for field {field_name!r} but got {type(resp_value).__name__}"
                )
            # Initialize nested list if missing
            if field_name not in last_applied_manifest or not isinstance(
                last_applied_manifest[field_name], list
            ):
                last_applied_manifest[field_name] = []
            # Delegate list handling to the corresponding function
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[field_name], field_spec, resp_value
            )
        # Scalar fields
        else:
            last_applied_manifest[field_name] = resp_value
<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    def _default_schema_for(resource):
        """Provide a minimal default schema based on the resource definition."""
        try:
            kind = resource.get("kind", "Unknown")
            api_version = resource.get("apiVersion", "v1")
        except AttributeError:
            kind = "Unknown"
            api_version = "v1"
        return {"kind": kind, "apiVersion": api_version}

    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("Missing 'spec' attribute on application object.")
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            # If the manifest is missing or not a dict, treat it as empty
            manifest = {}
        observer_schemas = getattr(spec, "observer_schemas", {})
        if observer_schemas is None:
            observer_schemas = {}
    except Exception as exc:
        raise ValueError(f"Invalid application object: {exc}") from exc

    if not isinstance(manifest, dict):
        raise TypeError(f"'manifest' must be a dict, got {type(manifest).__name__}")

    # Ensure observer_schemas is a dict
    if not isinstance(observer_schemas, dict):
        raise TypeError(f"'observer_schemas' must be a dict, got {type(observer_schemas).__name__}")

    # Generate defaults for missing schemas
    for resource_id, resource_def in manifest.items():
        if resource_id not in observer_schemas:
            # If resource_def is not a dict, skip generation
            if not isinstance(resource_def, dict):
                continue
            observer_schemas[resource_id] = _default_schema_for(resource_def)

    # Attach the updated schemas back to the app
    try:
        setattr(spec, "observer_schemas", observer_schemas)
    except Exception as exc:
        raise ValueError(f"Failed to set 'observer_schemas' on spec: {exc}") from exc

    # No explicit return value; the function mutates the app object in place.<|return|>

