    """Return string representation of validation log, with optional prefix."""
    try:
        # Normalize prefix to string
        if not isinstance(prefix, str):
            try:
                prefix = str(prefix)
            except Exception:
                prefix = ''
        # Attempt to retrieve the log; if missing, return a default message
        log = getattr(self, 'log', None)
        if log is None:
            return f"{prefix}No log available."
        if not isinstance(log, (list, tuple)):
            return f"{prefix}Invalid log format."
        # Build status lines
        lines = []
        for entry in log:
            if isinstance(entry, dict):
                # Expecting a 'message' field
                msg = entry.get('message')
                if msg is None:
                    msg = str(entry)
            elif isinstance(entry, (list, tuple)):
                # Use the last element as message if possible
                msg = entry[-1] if entry else ''
            else:
                msg = str(entry)
            lines.append(f"{prefix}{msg}")
        return '\n'.join(lines) or f"{prefix}Log is empty."
    except Exception as exc:
        return f"{prefix}Error retrieving status log: {exc}"<|return|>

