        """Check all digests in manifest that are needed are present and used."""
        # Validate input types
        if not isinstance(manifest_files, (list, tuple, dict)):
            raise TypeError("manifest_files must be a list, tuple, or dict")
        if not isinstance(digests_used, (set, list, tuple)):
            raise TypeError("digests_used must be a set, list, or tuple")

        digests_used_set = set(digests_used)
        digests_present_set = set()

        # Extract digests from the manifest representation
        if isinstance(manifest_files, dict):
            for key, value in manifest_files.items():
                if isinstance(value, dict) and "digest" in value:
                    digests_present_set.add(value["digest"])
                elif isinstance(value, str):
                    digests_present_set.add(value)
                elif isinstance(value, (list, tuple)):
                    for v in value:
                        if isinstance(v, str):
                            digests_present_set.add(v)
        else:
            for item in manifest_files:
                if isinstance(item, dict) and "digest" in item:
                    digests_present_set.add(item["digest"])
                elif isinstance(item, str):
                    digests_present_set.add(item)
                elif isinstance(item, (list, tuple)):
                    for v in item:
                        if isinstance(v, str):
                            digests_present_set.add(v)

        # Determine mismatches
        missing = digests_used_set - digests_present_set
        unused = digests_present_set - digests_used_set

        if missing or unused:
            message_parts = []
            if missing:
                message_parts.append(
                    f"Missing digests not found in manifest: {sorted(missing)}"
                )
            if unused:
                message_parts.append(
                    f"Digests present in manifest but unused: {sorted(unused)}"
                )
            raise ValueError("; ".join(message_parts))<|return|>

