def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from each file basename (excluding extension) to a list of full
        paths of files that share that basename.
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    try:
        import os
    except Exception as exc:
        raise RuntimeError(f"Unable to import necessary modules: {exc}") from exc

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Specified folder does not exist or is not a directory: {folder}")

    data = {}
    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if not os.path.isfile(full_path):
                continue
            base, _ = os.path.splitext(entry)
            data.setdefault(base, []).append(full_path)
        # Sort the lists for deterministic output
        for base in data:
            data[base].sort()
    except Exception as exc:
        raise RuntimeError(f"Failed to explore folder '{folder}': {exc}") from exc

    return data<|return|>

