def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Ensure indent is a non‑negative integer
    try:
        indent = int(indent)
    except Exception:
        indent = 0
    if indent < 0:
        indent = 0
    ind = " " * indent

    def _repr(value, level):
        """Helper to get a pretty representation of a sub‑object."""
        if hasattr(value, "pretty") and callable(value.pretty):
            try:
                return value.pretty(indent=level + 2, debug=debug).lstrip()
            except Exception:
                return repr(value)
        elif isinstance(value, (dict, list, tuple, set)):
            try:
                import pprint

                return pprint.pformat(value, width=80, indent=level + 2, compact=True)
            except Exception:
                return repr(value)
        else:
            return repr(value)

    try:
        if hasattr(self, "__dict__"):
            parts = []
            for attr in sorted(self.__dict__):
                val = self.__dict__[attr]
                part = f"{ind}{attr}:\n{_repr(val, indent)}"
                parts.append(part)
            body = "\n".join(parts)
            result = f"{self.__class__.__name__}(\n{body}\n{ind})"
        else:
            # Fallback for objects without a __dict__
            result = _repr(self, indent)
    except Exception:
        result = repr(self)

    if debug:
        result += f"  # type: {type(self).__name__}"
    return result
<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper to identify logical operators by name
    def _operator_name(expr):
        func = getattr(expr, 'func', None)
        if func is None:
            return None
        # For objects like functools.partial or other wrappers we try __name__
        name = getattr(func, '__name__', None)
        if name is None:
            name = getattr(func, '__class__', None)
            if name is not None:
                name = getattr(name, '__name__', None)
        return name.lower() if isinstance(name, str) else None

    # Simple predicates for logical operators
    def _is_and(expr):
        return _operator_name(expr) in ('and', 'and_', '&')

