def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("Hook cannot be None")

    def decorator(func):
        if not callable(func):
            raise TypeError("Handler must be callable")
        try:
            handlers = getattr(self, "_registry", None)
            if handlers is None:
                # Lazy creation of the registry if it doesn't exist yet
                handlers = {}
                setattr(self, "_registry", handlers)
            handlers.setdefault(hook, []).append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook '{hook}': {exc}") from exc
        return func

    return decorator<|return|>

