    """Wrap a tzname-like function so that, in Python 2, unicode output is
    converted to a byte string (UTF‑8).  In Python 3 the function is returned
    unchanged.
    """
    def _wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        try:
            # basestring only exists in Python 2
            basestring
        except NameError:
            # Python 3: nothing to do, just return the value
            return name
        else:
