def get_versions():
    """Get version information or return default if unable to do so."""
    # First attempt: Use pkg_resources if available
    try:
        import pkg_resources
        # Replace 'your-package-name' with the actual distribution name if known.
        # If the function is used within a package, you can use __name__ split.
        dist_name = __name__.split('.')[0]
        return pkg_resources.get_distribution(dist_name).version
    except Exception:
        pass

    # Second attempt: Read from a 'VERSION' file relative to this module
    try:
        import os
        import pkgutil
        data = pkgutil.get_data(__name__, "VERSION")
        if data:
            return data.decode().strip()
    except Exception:
        pass

    # Fallback default version
    return "0.0.0"<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Basic validation
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    # Convert pieces to strings
    try:
        pieces = [str(p) for p in pieces]
    except Exception as exc:
        raise ValueError("All pieces must be convertible to string") from exc

    # Normalize the style string for case-insensitive comparison
    style = style.strip().lower()

    # Handle empty pieces
    if not pieces:
        return ""

    # Rendering based on the requested style
    if style == "plain":
        return "\n".join(pieces)
    if style == "comma":
        return ", ".join(pieces)
    if style == "markdown":
        return "\n".join(f"- {p}" for p in pieces)
    if style == "json":
        try:
            import json
            return json.dumps(pieces, ensure_ascii=False)
        except Exception as exc:
            raise ValueError(f"Failed to serialize to JSON: {exc}") from exc
    if style == "html":
        # Simple HTML list
        items = "".join(f"<li>{p}</li>" for p in pieces)
        return f"<ul>{items}</ul>"

    # Unknown style
    raise ValueError(f"Unrecognized style: {style}")<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import shlex, subprocess, os

    # Validate and prepare command list
    if isinstance(commands, str):
        cmd_list = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("`commands` must be a str, list, or tuple.")
    if not isinstance(args, (list, tuple)):
        raise TypeError("`args` must be a list or tuple.")

    cmd_list.extend(args)

    # Verbose output
    if verbose:
        print(f"Executing command: {' '.join(cmd_list)}")

    # Environment handling
    env_proc = None
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("`env` must be a dict or None.")
        env_proc = {**os.environ, **env}

    # Subprocess arguments
    kwargs = {
        "cwd": cwd,
        "text": True,
        "capture_output": True,
        "env": env_proc,
    }
    if hide_stderr:
        kwargs["stderr"] = subprocess.DEVNULL

    # Run the command safely
    try:
        result = subprocess.run(cmd_list, **kwargs)
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd_list[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute command: {' '.join(cmd_list)}") from exc

    # When hide_stderr is True, return an empty string for stderr
    if hide_stderr and result.stderr is not None:
        result.stderr = ""

    return result<|return|>

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    The function can be used in two ways:

    1. As a decorator with a single argument:

        @register_vcs_handler('git')
        def handler(...)
            ...

    2. With the handler function supplied directly:

        @register_vcs_handler('svn', handler_func)
        def handler_func(...)
            ...
    """
    # Retrieve or create a registry attached to this function.
    registry = getattr(register_vcs_handler, "_registry", {})
    # If ``method`` is not provided, ``register_vcs_handler`` was called
    # with only the VCS identifier and should return a decorator.
    if method is None:
        def decorator(func):
            if not callable(func):
                raise TypeError(f"Expected a callable for handler, got {type(func).__name__}")
            if not isinstance(vcs, (str, int, float)):
                raise TypeError(f"VCS identifier must be a string or number, got {type(vcs).__name__}")
            registry[vcs] = func
            # Persist the registry on the function object for later use.
            setattr(register_vcs_handler, "_registry", registry)
            return func
        return decorator

    # Direct usage: handler function supplied directly.
    if not callable(method):
        raise TypeError(f"Expected a callable for handler, got {type(method).__name__}")
    if not isinstance(vcs, (str, int, float)):
        raise TypeError(f"VCS identifier must be a string or number, got {type(vcs).__name__}")
    registry[vcs] = method
    setattr(register_vcs_handler, "_registry", registry)
    return method

# Optional helper to retrieve a registered handler.
def get_vcs_handler(vcs):
    """Return the handler registered for the given VCS identifier, or None if not found."""
    registry = getattr(register_vcs_handler, "_registry", {})
    return registry.get(vcs, None)<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Collect objects via depth‑first traversal starting from the root.
    def _collect(obj):
        """Yield an object and all of its descendants."""
        yield obj
        # Allow objects to expose children via either `children` or `objects`
        children = getattr(obj, 'children', None)
        if children is None:
            children = getattr(obj, 'objects', [])
        if not isinstance(children, (list, tuple)):
            children = []
        for child in children:
            for grandchild in _collect(child):
                yield grandchild

    # Determine the starting point for traversal.
    try:
        root = getattr(self, 'root', None)
        if root is None:
            root = getattr(self, 'root_obj', None)
        if root is None:
            root = self
    except Exception:
        # If we can't determine a root, return zeros.
        if show_warnings:
            print("Warning: Unable to locate root for hierarchy validation.")
        return 0, 0

    # Perform validation.
    num_objects = 0
    good_objects = 0

    try:
        for obj in _collect(root):
            # Count the object.
            num_objects += 1
            is_valid = True

            # Validate object structure or status if requested.
            if validate_objects:
                try:
                    # Assume object provides an `is_valid()` method or similar.
                    is_valid = getattr(obj, 'is_valid', lambda: False)()
                except Exception:
                    is_valid = False

            # Validate digest checks if requested and prior checks passed.
            if check_digests and is_valid:
                try:
                    # Assume object provides a `verify_digest()` method returning bool.
                    is_valid = getattr(obj, 'verify_digest', lambda: True)()
                except Exception:
                    is_valid = False

            if is_valid:
                good_objects += 1
    except Exception as exc:
        # Any error during traversal invalidates the entire process.
        if show_warnings:
            print(f"Warning: validation aborted due to an error: {exc}")
        return num_objects, good_objects  # Return counts as far as we've gotten.

    if show_warnings and good_objects < num_objects:
        print(f"Warning: {good_objects} of {num_objects} objects passed validation; {num_objects - good_objects} failed.")
    return num_objects, good_objects<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("empty version string")

    parts = version.split('.')
    # Reject empty parts which indicate malformed input like "1..2" or "1."
    if any(p == '' for p in parts):
        raise ValueError("invalid version format")

    # Find the last numeric part that is all digits
    last_part = parts[-1]
    if not last_part.isdigit():
        raise ValueError(f"non-numeric part detected: '{last_part}'")

    # Preserve leading zeros for the incremented part
    width = len(last_part)
    try:
        incremented = str(int(last_part) + 1)
    except ValueError as exc:
        raise ValueError(f"cannot increment part '{last_part}': {exc}") from exc

    if len(incremented) < width:
        incremented = incremented.rjust(width, '0')

    new_parts = parts[:-1] + [incremented]
    return '.'.join(new_parts)<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Ensure the path is a string; if not, return an error message.
    if not isinstance(path, str):
        return f"Invalid path type: {type(path).__name__} (expected str)"

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # Read the directory contents safely
            try:
                entries = os.listdir(path)
            except PermissionError:
                return f"Permission denied: {path}"
            except OSError as e:
                return f"Error reading directory '{path}': {e}"

            namaste_files = [e for e in entries if e.startswith("0=")]
            if not namaste_files:
                return f"Unknown directory type (no Namaste files found) in {path}"

            # Sort to have deterministic output
            namaste_files.sort()

            # Check known Namaste file patterns
            if "0=repo" in namaste_files:
                return "root"
            # OCFL objects typically contain "0=object" or "0=shared" (shared objects)
            if any(name in (["0=object", "0=shared"]) for name in namaste_files):
                return "object"

            # Unknown Namaste file type; return the first one as hint
            return f"Unknown directory type (Namaste file: {namaste_files[0]}) in {path}"

        # If it's neither a file nor a directory (e.g., a symlink, socket, etc.)
        if os.path.islink(path):
            try:
                target = os.readlink(path)
                return f"Symlink to {target}"
            except OSError as e:
                return f"Symlink error for {path}: {e}"
        return f"Unsupported path type at {path}"

    except Exception as exc:
        # Catch any unforeseen exceptions to avoid crash
        return f"Error determining path type for '{path}': {exc}"<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params

    Parameters
    ----------
    params : dict
        Existing parameters dictionary to be amended.
    bug_ids : int, str, or iterable of int/str
        Bug ID(s) to include in params. Accepts a single integer, a
        comma‑separated string, or an iterable of integers/strings.

    Returns
    -------
    dict
        The amended parameters dictionary containing an 'ids' key with
        comma‑separated bug IDs.

    Raises
    ------
    ValueError
        If the inputs are of an unsupported type or contain invalid
        bug IDs.
    """
    # Ensure params is a dictionary
    if params is None:
        params = {}
    elif not isinstance(params, dict):
        raise ValueError("params must be a dict")

    # If no bug_ids provided, return unchanged params
    if bug_ids is None:
        return params

    # Collect bug IDs into a list of integers
    ids = []

    # Handle single integer
    if isinstance(bug_ids, int):
        ids.append(bug_ids)

    # Handle comma-separated string
    elif isinstance(bug_ids, str):
        for part in bug_ids.split(","):
            part = part.strip()
            if part:
                try:
                    ids.append(int(part))
                except ValueError as exc:
                    raise ValueError(f"Invalid bug ID string component '{part}'") from exc

    # Handle iterable of ints or strings
    elif hasattr(bug_ids, "__iter__"):
        for item in bug_ids:
            if isinstance(item, int):
                ids.append(item)
            elif isinstance(item, str):
                item = item.strip()
                if item:
                    try:
                        ids.append(int(item))
                    except ValueError as exc:
                        raise ValueError(f"Invalid bug ID string component '{item}'") from exc
            else:
                raise ValueError(f"Unsupported bug ID type: {type(item).__name__}")

    else:
        raise ValueError("bug_ids must be an int, string, or iterable of ints/strings")

    # Remove duplicates while preserving order
    seen = set()
    uniq_ids = []
    for i in ids:
        if i not in seen:
            seen.add(i)
            uniq_ids.append(i)

    # If we have IDs, add or update the 'ids' parameter
    if uniq_ids:
        params["ids"] = ",".join(str(i) for i in uniq_ids)

    return params<|return|>

def deep_merge_nodes(nodes):
    '''
    Merge a list of (key_node, value_node) tuples by combining duplicate keys.
    If duplicate keys point to MappingNode values, merge their contents recursively.
    For non-mapping values, the last value wins.

    Parameters
    ----------
    nodes : list[tuple]
        List of tuples where the first element is a ScalarNode key and the second
        is a value node (MappingNode or other). The function returns a new list
        with merged nodes.

    Returns
    -------
    list
        A new list of tuples with merged values.
    '''

    def merge_mapping(existing_map_node, new_map_node):
        try:
            existing_entries = existing_map_node.value
            new_entries = new_map_node.value
        except AttributeError:
            # If nodes don't have a `value` attribute, skip merging.
            return

        # Use an ordered dictionary logic by preserving the order of existing entries.
        existing_dict = {k_node.value: (k_node, v_node) for k_node, v_node in existing_entries}

        for k_node, v_node in new_entries:
            key_val = k_node.value
            if key_val in existing_dict:
                _, existing_v_node = existing_dict[key_val]
                if isinstance(existing_v_node, type(new_map_node)) and isinstance(v_node, type(new_map_node)):
                    # Recursively merge nested MappingNodes
                    merge_mapping(existing_v_node, v_node)
                else:
                    # Replace with the new value node
                    existing_dict[key_val] = (k_node, v_node)
            else:
                existing_dict[key_val] = (k_node, v_node)

        # Rebuild the entries list in the original order, preserving existing keys first
        # and then appending any new keys that weren't present before.
        updated_entries = list(existing_dict.values())
        existing_map_node.value = updated_entries

    merged_result = {}
    for key_node, val_node in nodes:
        try:
            key_id = key_node.value
        except AttributeError:
            # If the key node doesn't have a value, treat it as unique each time.
            key_id = id(key_node)

        if key_id in merged_result:
            existing_key, existing_val = merged_result[key_id]
            if isinstance(existing_val, type(val_node)) and isinstance(val_node, type(val_node)):
                # Both are MappingNodes of the same type; deep merge
                try:
                    merge_mapping(existing_val, val_node)
                except Exception:
                    # If merging fails, fallback to replacing
                    merged_result[key_id] = (key_node, val_node)
            else:
                # Replace the value with the new one
                merged_result[key_id] = (key_node, val_node)
        else:
            merged_result[key_id] = (key_node, val_node)

    return list(merged_result.values())
