def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    # Minimal custom ArgumentParser implementation
    class SimpleNamespace:
        def __init__(self, **kwargs):
            self.__dict__.update(kwargs)

        def __repr__(self):
            attrs = ', '.join(f"{k}={v!r}" for k, v in self.__dict__.items())
            return f"{self.__class__.__name__}({attrs})"

    class SimpleArgumentParser:
        def __init__(self, *args, **kwargs):
            # Store definitions of arguments (name -> settings)
            self._arg_defs = {}
            self._positional_defs = []

        def add_argument(self, name, *add_args, **kwargs):
            """Register a command-line argument.
            Supports:
                - Positional arguments if name does not start with '-'
                - Optional arguments starting with '-' (short) or '--' (long)
            """
            if not isinstance(name, str):
                raise TypeError("Argument name must be a string")
            if name.startswith('-'):
                self._arg_defs[name] = kwargs
            else:
                self._positional_defs.append(name)

        def parse_args(self, args_list):
            """Parse a list of arguments.
            Returns a SimpleNamespace with parsed values.
            """
            parsed = {}
            it = iter(args_list)
            # First handle optionals
            for token in it:
                if token.startswith('-'):
                    # Long or short option
                    if '=' in token:
                        key, value = token.split('=', 1)
                    else:
                        key = token
                        try:
                            value = next(it)
                        except StopIteration:
                            value = None
                    nice_name = key.lstrip('-').replace('-', '_')
                    parsed[nice_name] = value
                else:
                    # Positional arguments are handled later
                    # Store back the first non-option token
                    remaining = [token] + list(it)
                    break
            else:
                remaining = []

            # Assign positional values
            for pos_name, value in zip(self._positional_defs, remaining):
                parsed[pos_name.replace('-', '_')] = value

            return SimpleNamespace(**parsed)

    # Create parser instance
    parser = SimpleArgumentParser()

    # Define some example arguments (can be modified as needed)
    parser.add_argument('-h', '--help', action='store_true',
                        help='show this help message and exit')
    parser.add_argument('-v', '--verbose', action='store_true',
                        help='increase output verbosity')
    parser.add_argument('--input', '-i', help='input file path')
    parser.add_argument('output', nargs='?', default=None,
                        help='output file path (positional)')

    try:
        # Parse provided arguments
        ns = parser.parse_args(arguments)
        # Attach parsed namespace to parser for reference if needed
        parser.parsed = ns
        return parser
    except Exception as e:
        # Handle parsing errors gracefully
        raise RuntimeError(f"Argument parsing failed: {e}") from e<|return|>

def deep_merge_nodes(nodes):
    """
    Merge duplicate keys in a list of (ScalarNode, value) pairs.
    MappingNode values are merged recursively; other values are overwritten by
    later ones. The function returns a new list of pairs.

    Nodes are assumed to be ruamel.yaml.nodes. The function does not modify the
    input objects; it constructs a new merged structure where possible.
    """
    if not hasattr(nodes, "__iter__"):
        raise TypeError("nodes must be an iterable of (ScalarNode, value) pairs")
    merged = {}
    key_order = []

    def is_mapping(n):
        return hasattr(n, "tag") and n.tag == "tag:yaml.org,2002:map"

    def merge_mapping_vals(map1, map2):
        """
        Merge two MappingNode.value lists, each being a list of (key_node, val_node).
        Returns a new merged list.
        """
        result = []
        inner_dict = {}
        inner_order = []

        def add_entry(k_node, v_node):
            key = (k_node.tag, k_node.value)
            if key in inner_dict:
                # Merge if both MappingNode
                existing = inner_dict[key]
                if is_mapping(existing[1]) and is_mapping(v_node):
                    merged_val = merge_mapping_vals(existing[1].value, v_node.value)
                    inner_dict[key] = (k_node, type(existing[1])(
                        tag=existing[1].tag,
                        value=merged_val
                    ))
                else:
                    # overwrite with last
                    inner_dict[key] = (k_node, v_node)
            else:
                inner_dict[key] = (k_node, v_node)
                inner_order.append(key)

        for k, v in map1:
            add_entry(k, v)
        for k, v in map2:
            add_entry(k, v)

        for key in inner_order:
            result.append(inner_dict[key])
        return result

    def merge_value(v1, v2):
        if is_mapping(v1) and is_mapping(v2):
            merged_list = merge_mapping_vals(v1.value, v2.value)
            return type(v1)(tag=v1.tag, value=merged_list)
        return v2

    for item in nodes:
        if not (isinstance(item, tuple) or isinstance(item, list)):
            raise ValueError("Each element must be a tuple/list of (key_node, value_node)")
        if len(item) != 2:
            raise ValueError("Each element must contain exactly two items")
        key_node, val_node = item
        if not hasattr(key_node, "tag") or not hasattr(key_node, "value"):
            raise ValueError("Key node must have tag and value attributes")
        key_id = (key_node.tag, key_node.value)
        if key_id in merged:
            # Merge values
            merged_val = merge_value(merged[key_id][1], val_node)
            merged[key_id] = (merged[key_id][0], merged_val)
        else:
            merged[key_id] = (key_node, val_node)
            key_order.append(key_id)

    # Build result list preserving original order of first occurrences
    result = [merged[k] for k in key_order]
    return result<|return|>

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Input validation
    if response is None:
        raise ValueError("response must not be None")
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if max_results is None:
        raise ValueError("max_results must not be None")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator yielding paged slices
    def _generator():
        try:
            for idx in range(0, len(response), max_results):
                yield response[idx : idx + max_results]
        except Exception as exc:
            # Ensure generator propagates any unexpected errors gracefully
            raise RuntimeError(f"Error while paging: {exc}") from exc

    return _generator()
<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for entry in iterator:
        if not isinstance(entry, dict):
            raise TypeError(f"Expected dict, got {type(entry).__name__}")
        for key, value in entry.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Dictionary values must be numeric, got {type(value).__name__} for key {key!r}")
            result[key] = result.get(key, 0) + value
    return result<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Directly treat None as a None string representation
    if val is None:
        return True
    # Check for common string representations of None
    if isinstance(val, str):
        cleaned = val.strip().lower()
        # Common placeholders that mean 'no value'
        none_values = {"none", "null", "nil", "n/a", "na", ""}
        return cleaned in none_values
    # Everything else is not a None string
    return False<|return|>

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError("parser argument cannot be None")
    # Attempt to access parser._actions; raise a clear error if unavailable
    try:
        actions = parser._actions
    except Exception as exc:
        raise TypeError(
            f"The provided object ({type(parser).__name__}) does not expose the expected "
            "argparse.ArgumentParser interface."
        ) from exc
    flags = []
    for action in actions:
        try:
            option_strings = getattr(action, 'option_strings', None)
        except Exception:
            continue
        if option_strings:
            # option_strings is typically a list or tuple; handle generically
            if isinstance(option_strings, (list, tuple)):
                flags.extend(option_strings)
            else:
                try:
                    for opt in option_strings:
                        flags.append(opt)
                except Exception:
                    continue
    return ' '.join(flags)<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate parameters
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list with at least two characters")
    if any(not isinstance(ch, str) or len(ch) != 1 for ch in alphabet):
        raise ValueError("each element of alphabet must be a single-character string")

    base = len(alphabet)

    # Handle zero explicitly, because the loop below would produce an empty string
    if number == 0:
        result = alphabet[0]
    else:
        negative = number < 0
        num = abs(number)
        digits: List[str] = []
        while num:
            num, rem = divmod(num, base)
            digits.append(alphabet[rem])
        if not digits:
            result = alphabet[0]  # fallback, should not happen
        else:
            result = ''.join(reversed(digits))
        if negative:
            result = '-' + result

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer")
        # Padding applies to the numeric part, not the optional leading '-'
        sign = '-' if result.startswith('-') else ''
        number_part = result.lstrip('-')
        if len(number_part) < padding:
            number_part = alphabet[0] * (padding - len(number_part)) + number_part
        result = sign + number_part

    return result<|return|>

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    The function modifies flow_params in place. If the structure contains
    nested dictionaries or lists of dictionaries, all occurrences of the
    specified key are updated to the register number.
    """
    try:
        if not isinstance(flow_params, dict):
            raise ValueError("flow_params must be a dictionary")
        if not isinstance(register_value, str):
            raise ValueError("register_value must be a string key")

        def _recurse(obj):
            if isinstance(obj, dict):
                for k, v in list(obj.items()):
                    if k == register_value:
                        obj[k] = register_number
                    else:
                        _recurse(v)
            elif isinstance(obj, list):
                for item in obj:
                    _recurse(item)

        _recurse(flow_params)
        return None
    except Exception as exc:
        raise ValueError(f"Failed to replace register value: {exc}") from exc<|return|>

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace(".", arg)<|return|>

def subclasses(cls): 
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("Expected a class as argument")
    result = set()
    try:
        direct_subs = cls.__subclasses__()
    except Exception:
        return result
    for sub in direct_subs:
        result.add(sub)
        try:
            result.update(subclasses(sub))
        except RecursionError:
            # Too deep recursion; skip further subclasses
            continue
        except Exception:
            # Skip any subclass that causes an error
            continue
    return result<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type checks
    if string is None or not isinstance(string, str):
        raise TypeError("string must be a non‑None str")
    if alphabet is None or not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of unique characters")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two characters")

    # Build a quick lookup for character → digit value
    digit_map = {char: idx for idx, char in enumerate(alphabet)}

    result = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"character '{ch}' not found in alphabet")
        result = result * base + digit_map[ch]
    return result<|return|>

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        if hasattr(os, "uname"):
            return os.uname().sysname.lower() == "darwin"
    except Exception:
        pass
    try:
        if hasattr(os, "environ"):
            return os.environ.get("OSTYPE", "").lower().startswith("darwin")
    except Exception:
        pass
    return False<|return|>

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        return re.sub(r'^[\'"]|[\'"]$', '', name)
    except Exception as exc:
        raise ValueError(f"unquote failed: {exc}") from exc<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if not freq_str:
        raise ValueError("Empty frequency string")
    low = freq_str.lower()
    if low == "always":
        return None

    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    count_str, unit = parts
    try:
        if '.' in count_str:
            number = float(count_str)
        else:
            number = int(count_str)
    except ValueError as exc:
        raise ValueError(f"Invalid numeric part in frequency: {frequency!r}") from exc

    unit_map = {
        "day": "days",
        "days": "days",
        "week": "weeks",
        "weeks": "weeks",
        "hour": "hours",
        "hours": "hours",
        "minute": "minutes",
        "minutes": "minutes",
        "second": "seconds",
        "seconds": "seconds",
    }

    unit_key = unit.lower()
    if unit_key not in unit_map:
        # Try stripping a trailing 's'
        if unit_key.endswith('s'):
            unit_key = unit_key[:-1]
        if unit_key not in unit_map:
            raise ValueError(f"Unknown time unit in frequency: {frequency!r}")

    timedelta_kwargs = {unit_map[unit_key]: number}
    try:
        return datetime.timedelta(**timedelta_kwargs)
    except Exception as exc:
        raise ValueError(f"Could not create timedelta from frequency: {frequency!r}") from exc<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Handle missing or non‑string input early
    if not isinstance(host, str) or not host.strip():
        return False

    host = host.strip().lower()

    # Common localhost aliases
    if host == "localhost":
        return True

    # Try resolving the host to an address; if we hit a known local address, it's local
    try:
        # Resolve hostname or IP into a list of (family, type, proto, canonname, sockaddr) tuples
        addrinfo = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
        for family, _, _, _, sockaddr in addrinfo:
            # For IPv4 we get a tuple (ip, port); for IPv6 we get (ip, port, flowinfo, scopeid)
            if family in (socket.AF_INET, socket.AF_INET6):
                ip = sockaddr[0]
                if ip == "127.0.0.1" or ip == "::1":
                    return True
    except (socket.gaierror, OSError):
        # The hostname could not be resolved or something else went wrong – treat it as non‑local
        pass

    # If the host string itself is a literal IP address, check directly
    try:
        if socket.inet_pton(socket.AF_INET6, host):
            return host == "::1"
    except OSError:
        pass  # Not a valid IPv6 literal

    try:
        if socket.inet_aton(host) == b"\x7f\x00\x00\x01":
            return True
    except OSError:
        pass  # Not a valid IPv4 literal

    return False<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Windows platform check
        if os.name != 'nt':
            return False

        # Git Bash (MINGW or MSYS) specific environment variable
        msystem = os.environ.get('MSYSTEM', '')
        if msystem.startswith(('MINGW', 'MSYS')):
            return True

        # Additional check: presence of common Git Bash command prefixed executable
        git_path = os.environ.get('PATH', '')
        # Look for the presence of "git.exe" in the PATH as an indicator
        for path_entry in git_path.split(os.pathsep):
            if path_entry.lower().endswith('git/bin') or path_entry.lower().endswith('git/bin/git.exe'):
                return True
        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False<|return|>

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise TypeError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer representing octal permissions")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Ensure the directory exists
    dirpath = os.path.dirname(config_filename)
    if dirpath:
        try:
            os.makedirs(dirpath, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories '{dirpath}': {exc}") from exc

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False.")

    # Write the file and set permissions
    try:
        with open(config_filename, "w", encoding="utf-8") as fh:
            fh.write(rendered_config)
        try:
            os.chmod(config_filename, mode)
        except OSError as exc:
            raise OSError(f"Failed to set permissions on '{config_filename}': {exc}") from exc
    except OSError as exc:
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc
<|return|>

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str) or not image_href.strip():
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid URI: {image_href}") from exc

    if not parsed.scheme or not parsed.netloc:
        raise ValueError(f"URI must contain scheme and netloc: {image_href}")

    use_ssl = parsed.scheme.lower() == "https"
    netloc = parsed.netloc

    # Try to find image_id in query parameters first
    image_id = None
    try:
        query_params = urllib.parse.parse_qs(parsed.query)
        if "image_id" in query_params:
            vals = query_params["image_id"]
            if vals:
                image_id = vals[0]
    except Exception:
        # If parsing query fails, ignore and fallback to path
        pass

    # If not found in query, fallback to last non-empty path component
    if not image_id:
        path_parts = [p for p in parsed.path.split("/") if p]
        if path_parts:
            image_id = path_parts[-1]
        else:
            raise ValueError(f"Could not extract image_id from path: {image_href}")

    image_id = image_id.strip()
    if not image_id:
        raise ValueError(f"Extracted image_id is empty for href: {image_href}")

    return (image_id, netloc, use_ssl)<|return|>

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a safe regex pattern.
    If strip is True, leading and trailing whitespace is removed.
    Returns a compiled re.Pattern object that matches the literal string.
    Any error in the input or regex compilation raises an exception.
    """
    # Validate input type
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")
    # Optionally strip whitespace
    if strip:
        pattern = pattern.strip()
    try:
        # Escape all regex metacharacters to match the string literally
        escaped = re.escape(pattern)
        # Compile and return the regex pattern
        return re.compile(escaped)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern: {exc}") from exc<|return|>

def is_ipv4(target):
    """
    Test if IPv4 address or not
    """
    try:
        # If target is already an IP address instance
        if isinstance(target, (ipaddress.IPv4Address, ipaddress.IPv6Address)):
            return isinstance(target, ipaddress.IPv4Address)
        # Try to create an IPv4 or IPv6 address from the input
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except (ValueError, TypeError):
        # Not a valid IP address
        return False<|return|>

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError("Unable to encode the string to UTF-8") from exc
    return obj<|return|>

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        :return: A new Bookmarks instance containing the deserialized bookmarks.
        :rtype: Bookmarks
        """
        # Validate that `values` is iterable and each element is a string
        try:
            raw_iter = iter(values)
        except TypeError as exc:
            raise TypeError("`values` must be an iterable of strings") from exc

        raw_list = []
        for idx, raw in enumerate(raw_iter):
            if not isinstance(raw, str):
                raise TypeError(
                    f"Element at index {idx} in `values` is not a string: {raw!r}"
                )
            raw_list.append(raw)

        # Attempt to parse each raw bookmark.  If the class defines a private
        # `_parse_raw` helper, use it; otherwise fall back to passing the raw
        # strings directly to the constructor.
        try:
            if hasattr(cls, "_parse_raw"):
                parsed = []
                for raw in raw_list:
                    try:
                        parsed.append(cls._parse_raw(raw))
                    except Exception as exc:
                        raise ValueError(
                            f"Error parsing bookmark '{raw}'"
                        ) from exc
                # We assume the constructor accepts an iterable of parsed
                # bookmark objects.
                return cls(parsed)
            else:
                # Directly pass the raw strings to the constructor if it
                # accepts such an iterable.
                return cls(raw_list)
        except Exception as exc:
            # Wrap any unexpected exception to provide a clearer error message.
            raise RuntimeError(
                "Failed to instantiate Bookmarks from raw values"
            ) from exc<|return|>

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # 1. Check that the candidate claims to provide the interface
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except AttributeError:
            errors.append("Iface does not have 'providedBy' method")
        else:
            if not provided:
                errors.append(f"Candidate {candidate!r} does not claim to provide {iface.__name__}")

    # Helper to get interface required items, with a fallback for old API
    def _get_interface_detail(attr_name):
        try:
            return getattr(iface, attr_name)
        except AttributeError:
            # Legacy fallback: the interface may expose attributes differently
            if hasattr(iface, "__dict__"):
                return {k: v for k, v in iface.__dict__.items() if not k.startswith("_")}
            return {}

    # 2. Verify required methods
    method_dict = _get_interface_detail("_required_methods")
    if not method_dict:
        # Try to extract methods by introspection (fallback)
        method_dict = {}
        for name, attr in iface.__dict__.items():
            if name.startswith("_"):
                continue
            if callable(attr):
                method_dict[name] = attr

    for name, iface_method in method_dict.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue
        c_method = getattr(candidate, name)
        if not callable(c_method):
            errors.append(f"Attribute '{name}' is not callable")
            continue

        # Compare signatures if possible
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(c_method)
            if iface_sig != cand_sig:
                errors.append(f"Signature mismatch for method '{name}': expected {iface_sig}, got {cand_sig}")
        except (ValueError, TypeError):
            # Unable to obtain signatures (e.g., builtins); skip comparison
            pass

    # 3. Verify required attributes
    attr_dict = _get_interface_detail("_required_attributes")
    if not attr_dict:
        # Fallback: look for attributes not callable in interface
        attr_dict = {}
        for name, attr in iface.__dict__.items():
            if name.startswith("_"):
                continue
            if not callable(attr):
                attr_dict[name] = attr

    for name in attr_dict.keys():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}'")

    # 4. Handle collected errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True
<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate satisfies the interface, otherwise raises
    a TypeError (or returns False if tentative=True).
    """
    import inspect

    # Ensure we are working with a class, not an instance
    if not isinstance(candidate, type):
        candidate = candidate.__class__

    # Quick check: subclass relation satisfies interface
    try:
        if issubclass(candidate, iface):
            return True
    except Exception:
        pass

    missing = []

    for name, val in iface.__dict__.items():
        # Skip private/dunder members unless they are protocol methods
        if name.startswith('_') and not (name.startswith('__') and name.endswith('__')):
            continue

        # Retrieve attribute from candidate; track missing ones
        try:
            cand_attr = getattr(candidate, name)
        except AttributeError:
            missing.append(name)
            continue

        # If interface defines a function or coroutine, candidate must provide a callable
        if inspect.isfunction(val) or inspect.iscoroutinefunction(val):
            if not callable(cand_attr):
                missing.append(name)
                continue

            # Compare signatures for a stricter check
            try:
                sig_iface = inspect.signature(val)
                sig_cand = inspect.signature(cand_attr)
                if sig_iface != sig_cand:
                    missing.append(name)
            except Exception:
                # If we can't compare signatures, just assume mismatch
                missing.append(name)
        # For methods wrapped in staticmethod/classmethod, inspect returns function
        elif isinstance(val, (staticmethod, classmethod)):
            # Extract the underlying function for comparison
            underlying = val.__func__
            if not callable(cand_attr):
                missing.append(name)
                continue
            try:
                sig_iface = inspect.signature(underlying)
                sig_cand = inspect.signature(cand_attr)
                if sig_iface != sig_cand:
                    missing.append(name)
            except Exception:
                missing.append(name)

    if missing:
        if tentative:
            return False
        raise TypeError(
            f"Candidate class '{candidate.__name__}' does not fulfill '{iface.__name__}' interface: "
            f"missing or incompatible implementations for {', '.join(missing)}"
        )

    return True<|return|>

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    try:
        del self[key]
    except Exception as e:
        # In case deletion fails for an unexpected reason, re‑raise the error
        raise e
    return value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Locate the frequency and data mappings
        freq_map = getattr(self, 'freq', None) or getattr(self, '_freq', None)
        data_map = getattr(self, 'data', None) or getattr(self, '_data', None) \
                   or getattr(self, 'store', None) or getattr(self, 'cache', None)

        if freq_map is None or data_map is None:
            raise AttributeError("popitem(): required attributes not found")

        if not data_map:
            raise KeyError("popitem(): dictionary is empty")

        # Find key with the smallest frequency (ties broken arbitrarily)
        min_key = None
        min_freq = None
        for key, f in freq_map.items():
            if min_freq is None or f < min_freq:
                min_freq = f
                min_key = key

        if min_key is None:
            raise KeyError("popitem(): dictionary is empty")

        # Remove and return the key/value pair
        value = data_map.pop(min_key)
        freq_map.pop(min_key, None)
        return (min_key, value)
    except Exception as exc:
        raise exc
<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Try to pop from the primary dict-like storage
        return self._dict.popitem(last=True)
    except AttributeError:
        # Fallback to common attribute names if _dict is not defined
        container = getattr(self, 'cache', None) or getattr(self, '_cache', None)
        if container and hasattr(container, 'popitem'):
            return container.popitem(last=True)
        raise AttributeError("No underlying dictionary or OrderedDict found.")
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")<|return|>

