def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    See the module docstring for details.

    """
    import datetime
    import re
    try:
        if isinstance(dt_str, bytes):
            dt_str = dt_str.decode("ascii")
    except Exception:
        raise ValueError("dt_str must be a string or bytes object") from None

    s = dt_str.strip()
    if not s:
        raise ValueError("Empty datetime string")

    # ---------- Normalize week-based dates ----------
    week_pat = re.compile(
        r"^(?P<year>\d{4})-?W(?P<week>\d{2})(-?(?P<day>\d))?$",
        re.ASCII,
    )
    m = week_pat.match(s)
    if m:
        year = int(m.group("year"))
        week = int(m.group("week"))
        day = int(m.group("day")) if m.group("day") else 1
        try:
            base_date = datetime.date.fromisocalendar(year, week, day)
        except ValueError as exc:
            raise ValueError(f"Invalid ISO week date: {s}") from exc
        # time and tz will be added later
        s = base_date.isoformat()
        # keep any time separator and beyond unchanged
        if "T" in dt_str or " " in dt_str:
            rest = dt_str.split("T", 1)[1] if "T" in dt_str else dt_str.split(" ", 1)[1]
            s += "T" + rest
        else:
            # only date
            pass
        # continue to next steps for time and tz
    else:
        # ---------- Normalize simple dates without separators ----------
        if (
            "-" not in s
            and len(s) in {4, 6, 8}
            and s.isdigit()
        ):
            if len(s) == 4:
                # just year
                s = f"{s}"
            elif len(s) == 6:
                s = f"{s[:4]}-{s[4:6]}"
            else:  # 8
                s = f"{s[:4]}-{s[4:6]}-{s[6:8]}"

    # ---------- Handle timezone ----------
    # Z -> +00:00
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    # ±HHMM -> ±HH:MM
    tz_offset_pattern = re.compile(r"(?P<sign>[+-])(?P<hour>\d{2})(?P<minute>\d{2})$")
    m = tz_offset_pattern.search(s)
    if m:
        s = s[: m.start()] + f"{m.group('sign')}{m.group('hour')}:{m.group('minute')}"
    # ±HH -> ±HH:00
    tz_simple_pattern = re.compile(r"(?P<sign>[+-])(?P<hour>\d{2})$")
    m = tz_simple_pattern.search(s)
    if m:
        s = s[: m.start()] + f"{m.group('sign')}{m.group('hour')}:00"

    # ---------- Final parse ----------
    try:
        result = datetime.datetime.fromisoformat(s)
    except Exception as exc:
        # Try to parse only date part if time part missing
        if "T" in s:
            # maybe wrong timezone format
            raise ValueError(f"Cannot parse ISO-8601 datetime: {dt_str}") from exc
        # fallback to date only
        try:
            result = datetime.datetime.combine(
                datetime.date.fromisoformat(s.split("T")[0]),
                datetime.time.min,
            )
        except Exception as exc2:
            raise ValueError(f"Cannot parse ISO-8601 datetime: {dt_str}") from exc2

    return result
<|return|>

def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only

    :param dt: The datetime on which to replace the time zone
    :param tzinfo: The :py:class:`datetime.tzinfo` subclass instance to assign to
        ``dt`` if (and only if) it is naive.
    :return: Returns an aware :py:class:`datetime.datetime`.
    """
    # Basic type checks
    if not hasattr(dt, "tzinfo") or not hasattr(dt, "replace"):
        raise TypeError("dt must be a datetime.datetime instance")
    if tzinfo is None:
        raise TypeError("tzinfo must not be None")
    # Ensure tzinfo looks like a tzinfo instance
    if not hasattr(tzinfo, "utcoffset"):
        raise TypeError("tzinfo must be a datetime.tzinfo instance")

    # If dt is naive, set the tzinfo
    try:
        if dt.tzinfo is None:
            return dt.replace(tzinfo=tzinfo)
    except Exception:
        # If replace fails for some reason, fall back to the original
        pass

    return dt<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # 1. Check for a public message
        if getattr(request, "is_public_message", None):
            if request.is_public_message():
                return True
        if isinstance(request, dict) and request.get("type") == "public":
            return True

        # 2. Check for a private message
        if getattr(request, "is_private_message", None):
            if request.is_private_message():
                return True
        if isinstance(request, dict) and request.get("type") == "private":
            return True

        # 3. Check for a legacy payload
        if getattr(request, "is_legacy_payload", None):
            if request.is_legacy_payload():
                return True
        if isinstance(request, dict) and request.get("legacy", False):
            return True

        # Not a Diaspora request
        return False

    except Exception:
        # In case of any unexpected errors, we treat as not a Diaspora request
        return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request

    Parameters
    ----------
    request : RequestType
        The request object to inspect.

    Returns
    -------
    bool
        ``True`` if the request appears to be a Matrix request, otherwise
        ``False``.
    """
    try:
        # 1. Check for a dedicated matrix attribute
        if getattr(request, "matrix", None) is not None:
            return True

        # 2. Inspect headers for a Matrix‑related content type
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            ct = headers.get("Content-Type", "") or headers.get("content-type", "")
            if isinstance(ct, str) and "matrix" in ct.lower():
                return True

        # 3. Look for JSON payload that contains a 'matrix' key
        # The request might expose a .json() method like Flask/Django requests
        json_body = None
        if hasattr(request, "json"):
            json_prop = getattr(request, "json")
            if callable(json_prop):
                try:
                    json_body = json_prop()
                except Exception:
                    pass
            else:
                json_body = json_prop
        if isinstance(json_body, dict) and "matrix" in json_body:
            return True

        # 4. Fallback: look for the word 'matrix' in the raw body/text
        body = getattr(request, "data", None) or getattr(request, "text", None)
        if isinstance(body, (str, bytes)):
            if isinstance(body, bytes):
                body = body.decode(errors="ignore")
            if "matrix" in body.lower():
                return True

    except Exception:
        # Any error in inspection should result in False
        return False

    return False<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure the input is a string
    if not isinstance(tag, str):
        raise TypeError("tag must be a string")

    # Strip surrounding whitespace
    tag = tag.strip()

    # Empty strings are not valid tags
    if not tag:
        return False

    # Maximum length of a tag (example constraint)
    MAX_LENGTH = 30
    if len(tag) > MAX_LENGTH:
        return False

    # First character must be a letter
    if not tag[0].isalpha():
        return False

    # Allowed characters: letters, digits, hyphen, underscore
    for ch in tag:
        if not (ch.isalnum() or ch in ("-", "_")):
            return False

    return True<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    from urllib.parse import urlparse

    try:
        if not isinstance(url, str):
            raise TypeError("url must be a string")
        parsed = urlparse(url)
        if not parsed.scheme or not parsed.netloc:
            raise ValueError(f"Invalid URL: {url}")

        # Normalise base URL by removing trailing slash
        base_url = url.rstrip("/")

        # Determine document path
        if document_path is None:
            document_path = "/nodeinfo/2.0"
        else:
            if not isinstance(document_path, str):
                raise TypeError("document_path must be a string")
            if not document_path.startswith("/"):
                raise ValueError("document_path must start with '/'")

        # Construct the href for the nodeinfo endpoint
        href = f"{base_url}{document_path}"

        # Build the .well-known NodeInfo document
        document = {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                    "href": href
                }
            ]
        }

        return document

    except Exception as exc:
        # For unexpected errors, re-raise to let caller handle
        raise ValueError(f"Failed to generate NodeInfo document: {exc}") from exc<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    from json import JSONDecodeError

    if not document or not isinstance(document, str):
        return {}

    # Strip leading whitespace to find first meaningful character
    stripped = document.lstrip()
    if stripped.startswith('{') or stripped.startswith('['):
        # Likely JSON
        try:
            return json.loads(document)
        except JSONDecodeError:
            # Fallback to XML parsing
            pass

    # Attempt to parse as XML (XRD)
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    # Helper to get namespace-less tag
    def strip_ns(tag):
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result: Dict[str, any] = {}
    subject = None
    # Find the Subject element (case-sensitive)
    for elem in root.iter():
        if strip_ns(elem.tag).lower() == 'subject':
            subject = elem.text.strip() if elem.text else None
            break
    if subject:
        result['subject'] = subject

    # Gather Link elements
    links = []
    for link_elem in root.iter():
        if strip_ns(link_elem.tag).lower() == 'link':
            link_dict = {}
            for attr_name, attr_value in link_elem.attrib.items():
                # Strip namespace from attribute names if any
                if attr_name.startswith('{'):
                    attr_name = attr_name.split('}', 1)[-1]
                if attr_value:
                    link_dict[attr_name] = attr_value
            if link_dict:
                links.append(link_dict)
    if links:
        result['links'] = links

    return result
<|return|>

