def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance or ``None`` if retrieval/parsing fails
    """
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    url = f"https://{host}/.well-known/host-meta"
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return None
            data = response.read()
    except (urllib.error.URLError, urllib.error.HTTPError, ValueError):
        # Invalid URL or network error
        return None

    try:
        root = ET.fromstring(data)
    except ET.ParseError:
        # Not a valid XML document
        return None

    # If the namespace is present, strip it for easier handling
    ns = {}
    if root.tag.startswith("{"):
        ns_uri = root.tag[1:].split("}")[0]
        ns = {"ns": ns_uri}

    # Build a simple XRD-like dictionary
    xrd_dict = {"links": []}
    for link in root.findall(".//{*}Link"):
        link_info = {}
        for attr in ["rel", "href", "type", "template"]:
            if attr in link.attrib:
                link_info[attr] = link.attrib[attr]
        if link_info:
            xrd_dict["links"].append(link_info)

    return xrd_dict if xrd_dict["links"] else None<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Import requests here to avoid global import requirement
    try:
        import requests
    except Exception as import_err:
        return (None, import_err)

    # Resolve the request method
    method_name = method.lower()
    if not hasattr(requests, method_name):
        # Unsupported method
        return (None, AttributeError(f"module 'requests' has no attribute '{method_name}'"))

    request_func = getattr(requests, method_name)

    try:
        # Perform the request with provided arguments
        response = request_func(url, data=data, timeout=timeout, *args, **kwargs)
        # Return status code and no error
        return (response.status_code, None)
    except Exception as exc:
        # Any exception: return None for status and the exception instance
        return (None, exc)<|return|>

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("key must be a string")

    chain = [key] + list(keys)
    current = dic

    for idx, k in enumerate(chain):
        if not isinstance(k, str):
            raise TypeError(f"key at position {idx} must be a string")
        if idx == len(chain) - 1:
            current[k] = val
        else:
            # If the key does not exist or is not a dict, set it to a new dict
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]
    return dic<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    # Validate inputs
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    try:
        os = __import__("os")
        re = __import__("re")
    except Exception as exc:
        raise ImportError("Required modules not available") from exc

    all_files = []
    pattern = None
    if spec_option:
        try:
            pattern = re.compile(spec_option)
        except re.error as exc:
            raise ValueError(f"Invalid regular expression for spec_option: {exc}") from exc

    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            continue
        if not os.path.isdir(dir_path):
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if pattern is None or pattern.search(entry):
                        all_files.append(entry)
        except Exception:
            # Skip directories that cannot be accessed
            continue

    # Return a sorted list of unique file names
    return sorted(set(all_files))<|return|>

