@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        try:
            if spec_content is None:
                raise IRValidatorException("spec_content is None")

            # Attempt to parse YAML content; yaml should be available in the environment.
            data = yaml.safe_load(spec_content)

            if not isinstance(data, dict):
                raise IRValidatorException("Spec content must be a mapping (dictionary).")

            # Define mandatory keys expected in the spec.
            required_keys = ["name", "version"]
            missing_keys = [key for key in required_keys if key not in data]
            if missing_keys:
                raise IRValidatorException(
                    f"Missing required fields in spec: {', '.join(missing_keys)}"
                )

            return data
        except IRValidatorException:
            # Re‑raise our specific validation exception unchanged.
            raise
        except Exception as exc:
            # Wrap any other exception as a validation error.
            raise IRValidatorException(f"Failed to validate spec content: {exc}") from exc<|return|>

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # ------------------------------------------------------------------
        # Import local dependencies, falling back if necessary
        # ------------------------------------------------------------------
        try:
            import yaml
        except Exception as exc:
            raise ImportError(
                "PyYAML is required to load YAML files. Original error: %s" %
                exc
            ) from exc

        # Try to import the custom exception if it exists
        try:
            from .exceptions import IRValidatorException
        except Exception:
            class IRValidatorException(Exception):
                """Fallback exception if custom one is not available."""
                pass

        # ------------------------------------------------------------------
        # Validate input and load YAML
        # ------------------------------------------------------------------
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided.")

        try:
            with open(yaml_file, "r", encoding="utf-8") as fp:
                data = yaml.safe_load(fp)
        except FileNotFoundError as exc:
            raise IRValidatorException(
                f"YAML file '{yaml_file}' not found."
            ) from exc
        except yaml.YAMLError as exc:
            raise IRValidatorException(
                f"Error parsing YAML file '{yaml_file}': {exc}"
            ) from exc
        except Exception as exc:
            raise IRValidatorException(
                f"Unexpected error reading YAML file '{yaml_file}': {exc}"
            ) from exc

        # ------------------------------------------------------------------
        # Validate structure
        # ------------------------------------------------------------------
        if not isinstance(data, dict):
            raise IRValidatorException(
                f"Expected YAML root to be a mapping, got {type(data).__name__}."
            )

        # Define required top‑level keys (can be customized by subclasses)
        # Subclass may override `REQUIRED_FIELDS` attribute; if missing, use defaults
        required_fields = getattr(cls, "REQUIRED_FIELDS", ["name", "metadata", "spec"])

        missing = [k for k in required_fields if k not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required field(s): {', '.join(missing)}"
            )

        # Additional field‑level validation could be implemented here if needed

        return data<|return|>

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Extract the 'include' directive and remove it from the input dictionary.
        include = parser_dict.pop('include', None)
        if include is None:
            return parser_dict
        if not isinstance(include, dict):
            raise ValueError(
                f"'include' directive must be a dict, got {type(include).__name__}"
            )
        # Merge each item from the include dict into the main parser dictionary.
        for key, value in include.items():
            if isinstance(value, dict):
                # Replace or add the key with the included dictionary.
                parser_dict[key] = value
            else:
                # Non-dict values are ignored because they cannot be merged meaningfully.
                continue
        return parser_dict<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: Mapping of argument names to their resolved default values.

    Raises:
        RuntimeError: If the specification format is invalid or an unexpected
                      error occurs during resolution.
    """
    try:
        # Retrieve the specification definition.
        spec = getattr(self, "spec", {})
        if not isinstance(spec, dict):
            raise TypeError("`self.spec` must be a dictionary.")

        # Determine the mapping of argument names to their specifications.
        arg_map = spec.get("args") or spec.get("arguments")
        if arg_map is None:
            # No arguments defined; return an empty mapping.
            return {}

        if not isinstance(arg_map, dict):
            raise TypeError("`spec['args']` or `spec['arguments']` must be a dictionary.")

        defaults = {}
        for name, arg_spec in arg_map.items():
            if not isinstance(arg_spec, dict):
                raise TypeError(f"Specification for argument '{name}' must be a dictionary.")

            # 1. Prefer an explicit 'default' entry in the specification.
            if "default" in arg_spec:
                defaults[name] = arg_spec["default"]
                continue

            # 2. Attempt to resolve the default from an alternative source
            #    (e.g., `self._get_default` if implemented).
            if hasattr(self, "_get_default"):
                try:
                    defaults[name] = self._get_default(name)
                    continue
                except Exception:
                    # If the helper fails, fall back to None below.
                    pass

            # 3. As a last resort, assign ``None`` to indicate no default.
            defaults[name] = None

        return defaults

    except Exception as exc:
        # Preserve original traceback while providing contextual information.
        raise RuntimeError(f"Error resolving spec defaults: {exc}") from exc<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints deprecated arguments.

    Parameters
    ----------
    cli_args : dict
        The dictionary of arguments passed through the CLI.
    answer_file_args : dict
        The dictionary of arguments loaded from answer files.
    """
    # Determine the set of deprecated arguments; external sources may define it
    deprecated = getattr(self, "deprecated_args", set())
    try:
        if not isinstance(cli_args, dict):
            raise TypeError("cli_args must be a dictionary")
        if not isinstance(answer_file_args, dict):
            raise TypeError("answer_file_args must be a dictionary")
        # Combine arguments; CLI args override file args if duplicate keys
        combined_args = {**answer_file_args, **cli_args}
        for key in combined_args.keys():
            if key in deprecated:
                message = f"Argument '{key}' is deprecated."
                print(message)
    except Exception as exc:
        # Reraise any exception after ensuring it is a DERAVException if possible
        raise exc from None<|return|>

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non‑empty string")
    try:
        # Try to locate the parser for the given command name.
        parser = None
        # Common pattern: self.parsers or similar dict mapping command names to parsers
        if hasattr(self, "parsers") and isinstance(self.parsers, dict):
            parser = self.parsers.get(command_name)
        # Fallback: inspect subparsers in a top‑level argparse parser
        if parser is None and hasattr(self, "parser"):
            subparsers_actions = getattr(self.parser, "_subparsers_actions", {})
            for action in subparsers_actions.values():
                choices = getattr(action, "choices", None)
                if choices and command_name in choices:
                    parser = choices.get(command_name)
                    break
        if parser is None:
            raise ValueError(f"No parser found for command '{command_name}'")

        # Collect all option strings defined in this parser
        options = set()
        for action in getattr(parser, "_actions", []):
            if action.option_strings:
                # Only keep explicit options (starting with '-') and skip positional args
                opts = [opt for opt in action.option_strings if opt.startswith("-")]
                options.update(opts)

        return sorted(options)
    except Exception as exc:
        raise RuntimeError(
            f"Error retrieving options for command '{command_name}': {exc}"
        ) from exc<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string.")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string.")

    # Ensure the commands configuration exists
    if not hasattr(self, "commands") or not isinstance(self.commands, dict):
        raise AttributeError("The object does not have a valid 'commands' dictionary.")

    # Retrieve the command entry
    command = self.commands.get(command_name)
    if command is None:
        raise KeyError(f"Command '{command_name}' not found.")

    # Retrieve the options dictionary for the command
    options = None
    if isinstance(command, dict):
        options = command.get("options")
    elif hasattr(command, "options"):
        options = command.options
    if options is None or not isinstance(options, dict):
        raise AttributeError(f"Command '{command_name}' does not have a valid options dictionary.")

    # Retrieve the specification for the given argument name
    spec = options.get(argument_name)
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'.")

    return spec.<|return|>

def get_silent_args(self, args):
    """
    Identify arguments whose values are considered 'silent' (i.e., no meaningful value).

    This function accepts a variety of argument representations (dictionary, list of tuples,
    argparse.Namespace) and returns a list of argument names that should be treated as
    silent. A silent argument is defined as one of the following:
        - The key is present but its value is None, False, an empty string, or an empty
          sequence/collection.
        - The key itself is a string that starts with an underscore ('_'), which is
          conventionally used to indicate private/ignored data.

    Parameters
    ----------
    args : Union[dict, argparse.Namespace, list, tuple]
        The received arguments in various expected forms.

    Returns
    -------
    list
        A list of argument names considered silent.
    """
    try:
        # Handle argparse.Namespace by converting to dict
        if hasattr(args, '__dict__'):
            args_dict = vars(args)
        else:
            args_dict = args

        if isinstance(args_dict, dict):
            silent_keys = []
            for key, value in args_dict.items():
                if not isinstance(key, str):
                    continue
                if key.startswith('_'):
                    silent_keys.append(key)
                    continue
                if value is None or value is False:
                    silent_keys.append(key)
                elif isinstance(value, (list, tuple, set)) and len(value) == 0:
                    silent_keys.append(key)
                elif isinstance(value, str) and value == '':
                    silent_keys.append(key)
            return silent_keys

        elif isinstance(args_dict, (list, tuple)):
            # Support a list of (key, value) tuples
            if all(isinstance(item, (list, tuple)) and len(item) == 2 for item in args_dict):
                silent_keys = []
                for key, value in args_dict:
                    if not isinstance(key, str):
                        continue
                    if key.startswith('_'):
                        silent_keys.append(key)
                        continue
                    if value is None or value is False:
                        silent_keys.append(key)
                    elif isinstance(value, (list, tuple, set)) and len(value) == 0:
                        silent_keys.append(key)
                    elif isinstance(value, str) and value == '':
                        silent_keys.append(key)
                return silent_keys

        # If args is a simple list/tuple of names, return empty list as no values to judge
        return []

    except Exception:
        # In case of unexpected input types, simply return an empty list
        return []<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary-like mapping
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    # Retrieve the collection of required argument names; default to empty iterable
    required = getattr(self, "requires_args", getattr(self, "required_args", []))
    if not hasattr(required, "__iter__"):
        raise TypeError("requires_args must be an iterable of keys")

    missing = []
    for key in required:
        if key not in args:
            missing.append(key)

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(map(str, missing))}")

    return True<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments. Expected to be a mapping (e.g. dict).
    """
    # Validate input type
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary or dict-like mapping.")

    # Retrieve the dict of allowed choices from the instance, if present.
    # It should be a mapping: {argument_name: iterable_of_acceptable_values}
    available_choices = getattr(self, "choices", {})
    if not isinstance(available_choices, dict):
        raise TypeError("`self.choices` must be a dictionary mapping argument names to allowed values.")

    # Iterate over all arguments that have defined choices
    for arg_name, accepted in available_choices.items():
        if arg_name not in args:
            # Argument not supplied; skip validation for this arg
            continue

        value = args[arg_name]

        # The accepted values may be any iterable; membership test works for sets,
        # lists, tuples, etc. Convert to a tuple for reproducible error messages.
        try:
            if value not in accepted:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of {sorted(set(accepted))}."
                )
        except TypeError as exc:
            # Membership test failed because ``accepted`` is not iterable.
            raise TypeError(
                f"The value of 'choices' for argument '{arg_name}' must be an iterable, "
                f"but got {type(accepted).__name__}."
            ) from exc
    # if no issues, simply return
    return None<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import os
    from pathlib import Path

    # Input validation
    if not isinstance(plugin_dir, (str, Path)):
        raise TypeError("plugin_dir must be a string or pathlib.Path instance")

    plugin_path = Path(plugin_dir).expanduser().resolve()

    if not plugin_path.is_dir():
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Supported spec filenames
    spec_filenames = ["plugin_spec.json", "plugin_spec.yaml", "plugin_spec.yml", "spec.json", "spec.yaml", "spec.yml"]
    spec_file = None
    for name in spec_filenames:
        candidate = plugin_path / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError("No spec file found in plugin directory")

    # Load spec (JSON or YAML)
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.suffix.lower() in {".json"}:
                spec_data = json.load(f)
            else:
                # Try yaml if available
                try:
                    import yaml
                except Exception:
                    raise RuntimeError("YAML spec file found but PyYAML is not installed")
                spec_data = yaml.safe_load(f)
    except Exception as exc:
        raise RuntimeError(f"Failed to load spec file: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError("Spec root must be a dictionary")

    # Helper to flatten dictionary
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    flat_dict = _flatten(spec_data)
    return flat_dict<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        # Determine the environment variable name to use
        env_var = getattr(self, 'config_env_var', None)
        if not env_var:
            env_var = 'CONFIG_PATH'
        # Get the configuration path from the instance
        config_path = getattr(self, 'config_path', None)
        if config_path is None:
            # No config path available; nothing to do
            return
        # If the env variable is not already set, inject it
        if env_var not in os.environ:
            os.environ[env_var] = config_path
    except Exception as exc:
        raise RuntimeError(f"Failed to inject config path into environment: {exc}") from exc<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os

    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")

    # Normalize both path and root
    path_norm = os.path.normpath(path)
    root_norm = os.path.normpath(root)

    # Ensure we are working with absolute or relative consistently
    # If root is absolute, path must also be absolute to be considered a match
    if os.path.isabs(root_norm) != os.path.isabs(path_norm):
        raise ValueError("Root and path must both be absolute or both be relative")

    # If root is empty, nothing to strip
    if root_norm and root_norm not in [os.path.sep, r"."]:
        # Add separator for matching, except on root of filesystem
        sep = os.path.sep
        if not root_norm.endswith(sep):
            root_norm += sep

        # Check if path starts with root (including separator)
        if path_norm.startswith(root_norm):
            stripped = path_norm[len(root_norm):]
            # Handle case where stripped is empty and original path was exactly root
            if stripped == '':
                return ''
            return stripped
        elif path_norm == root_norm.rstrip(sep):
            # path exactly equals root (without trailing separator)
            return ''
        else:
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    else:
        # root is root of filesystem or empty: strip nothing
        if path_norm == root_norm:
            return ''
        else:
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")<|return|>
